<script setup>
import { computed } from 'vue';
import { Link, usePage } from '@inertiajs/vue3';
import AppIcon from './AppIcon.vue';
const emit=defineEmits(['navigate']);const page=usePage();const user=computed(()=>page.props.auth.user);const internal=computed(()=>user.value?.role!=='vendor');const admin=computed(()=>user.value?.role==='admin');
const initials=computed(()=>user.value.name.split(/\s+/).filter(Boolean).slice(0,2).map(v=>v[0]).join('').toUpperCase());
const groups=computed(()=>[
 {label:'Utama',items:[{key:'home',label:'Dashboard',icon:'warehouse',url:page.props.routes.home}]},
 ...(internal.value?[{label:'Transaksi',items:[{key:'manual-data-in',label:'Data IN',icon:'arrowDown',url:page.props.routes.manualDataInIndex},{key:'material-requests',label:'Data OUT / Material Request',icon:'box',url:page.props.routes.materialRequestsIndex}]}]:[]),
 {label:'Pengadaan',items:[{key:'procurement',label:'PR, PO & Dokumen',icon:'layers',url:page.props.routes.procurementIndex}]},
 {label:'Monitoring',items:[...(internal.value?[{key:'monitoring-transactions',active:'monitoring',label:'Rekap Transaksi',icon:'layers',url:page.props.routes.monitoringTransactionsIndex},{key:'monitoring-shifts',active:'monitoring',label:'Rekap Shift',icon:'layers',url:page.props.routes.monitoringShiftsIndex}]:[]),{key:'monitoring-reconciliations',active:'monitoring',label:'BA Rekonsiliasi',icon:'checkCircle',url:page.props.routes.monitoringReconciliationsIndex},{key:'monitoring-stock',active:'monitoring',label:'Stock Sistem',icon:'warehouse',url:page.props.routes.monitoringSystemStockIndex}]},
 {label:'Vendor & Refill',items:[{key:'refills',label:'Vendor Refill',icon:'truck',url:page.props.routes.refillsIndex},...(internal.value?[{key:'incoming-refills',label:'Incoming Refill',icon:'arrowDown',url:page.props.routes.incomingRefillsIndex}]:[])]},
 ...(internal.value?[{label:'Master & Tools',items:[{key:'items',label:'Master Part',icon:'box',url:page.props.routes.itemsIndex},{key:'categories',label:'Kategori',icon:'layers',url:page.props.routes.categoriesIndex},{key:'departments',label:'Departemen',icon:'layers',url:page.props.routes.departmentsIndex},{key:'vendors',label:'Vendor',icon:'truck',url:page.props.routes.vendorsIndex},{key:'units',label:'Satuan',icon:'ruler',url:page.props.routes.unitsIndex},{key:'locations',label:'Lokasi',icon:'pin',url:page.props.routes.locationsIndex},...(page.props.navigation.can_import?[{key:'imports',label:'Import Master PN',icon:'upload',url:page.props.routes.importsIndex}]:[]),...(admin.value?[{key:'users',label:'User Management',icon:'shield',url:page.props.routes.usersIndex}]:[]),{key:'opening-balances',label:'Saldo Awal',icon:'upload',url:page.props.routes.openingBalancesIndex},{key:'stock-corrections',label:'Koreksi Stok',icon:'shield',url:page.props.routes.stockCorrectionsIndex},{key:'shifts',label:'Pengaturan Shift',icon:'layers',url:page.props.routes.shiftsIndex}]}]:[])
]);
</script>
<template><div class="sidebar-content"><div class="sidebar-brand"><span class="sidebar-brand__mark"><AppIcon name="warehouse"/></span><div><span class="sidebar-brand__name">WAREHOUSE</span><span class="sidebar-brand__sub">SYSTEM</span></div></div><nav class="sidebar-nav" aria-label="Navigasi utama"><p class="sidebar-section-label">AREA KERJA</p><div v-for="group in groups" :key="group.label"><div class="nav-group-label"><AppIcon name="layers"/><span>{{group.label}}</span></div><div class="nav-children"><Link v-for="item in group.items" :key="item.key" :href="item.url" class="nav-item" :class="{'nav-item--active':page.props.navigation.current===(item.active||item.key)}" @click="emit('navigate')"><span class="nav-item__icon"><AppIcon :name="item.icon"/></span><span>{{item.label}}</span><span v-if="page.props.navigation.current===(item.active||item.key)" class="nav-item__active-dot"/></Link></div></div></nav><div class="sidebar-footer"><div class="sidebar-access"><AppIcon name="shield"/><span>{{user.role==='vendor'?'Akses vendor':'Akses internal'}}</span></div><div class="sidebar-user"><span class="avatar">{{initials}}</span><div class="sidebar-user__identity"><span>{{user.name}}</span><small>{{user.role_label}}</small></div></div><Link :href="page.props.routes.logout" method="post" as="button" class="sidebar-logout"><AppIcon name="logout"/><span>Keluar</span></Link></div></div></template>
